import{_ as o,a0 as l,w as r,s as u,ao as n,I as i,x as a,a1 as p,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"为你的 Linux 应用创建 .desktop 文件 | LCTT x X-CMD","titleTemplate":false,"description":"为你的 Linux 应用创建 .desktop 文件 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为你的 Linux 应用创建 .desktop 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为你的 Linux 应用创建 .desktop 文件 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171218 How to Create a .Desktop File For Your Application in Linux","title":"为你的 Linux 应用创建 .desktop 文件","tag":"201801","desc":""},"relativePath":"201801/20171218 How to Create a .Desktop File For Your Application in Linux.md","filePath":"[post].md"}'),c={name:"201801/20171218 How to Create a .Desktop File For Your Application in Linux.md"};function d(h,e,m,k,g,w){const t=l("Link");return r(),u("div",null,[e[16]||(e[16]=n('<h1 id="为你的-linux-应用创建-desktop-文件" tabindex="-1">为你的 Linux 应用创建 .desktop 文件 <a class="header-anchor" href="#为你的-linux-应用创建-desktop-文件" aria-label="Permalink to “为你的 Linux 应用创建 .desktop 文件”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2017/12/application-launcher-featured.jpg" alt=""></p><p>在 Linux 中，一个 <code>.desktop</code> 文件就是一个用来运行程序的快捷方式。没有 <code>.desktop</code> 的话，你的应用就不会在应用菜单中显示了，也无法使用像 Synapse 和 Albert 这样的第三方启动起启动了。</p><p>大多数应用在安装后都会自动创建 <code>.desktop</code> 文件，并将自己放入应用菜单中以方便访问。然而，如果是你自己从源代码中编译的程序或者自己下载的压缩格式的应用，那就不会做这些事情了，每次你都需要打开终端来执行它的二进制文件。显然这个过程很无聊也很麻烦。</p><p>本文将会告诉你如何为应用创建 <code>.desktop</code> 文件，从而让你能在应用菜单中启动该应用。</p>',5)),i("p",null,[e[1]||(e[1]=i("strong",null,"相关阅读",-1)),e[2]||(e[2]=a("：",-1)),p(t,{href:"https://www.maketecheasier.com/add-app-drawer-unity-launcher-ubuntu/",title:"How to Add App Drawers to Unity Launcher in Ubuntu"},{default:s(()=>[...e[0]||(e[0]=[a("How to Add App Drawers to Unity Launcher in Ubuntu",-1)])]),_:1})]),e[17]||(e[17]=n(`<h3 id="如何创建桌面启动器" tabindex="-1">如何创建桌面启动器 <a class="header-anchor" href="#如何创建桌面启动器" aria-label="Permalink to “如何创建桌面启动器”">​</a></h3><p><code>.desktop</code> 文件基本上就是一个包含程序信息的纯文本文件，通常根据是自己可见还是所有用户可见的不同而放在 <code>~/.local/share/applications</code> 或者 <code>/usr/share/applications/</code> 目录中。你在文件管理器中访问这两个目录，都会看到很多系统中已安装应用对应的 <code>.desktop</code> 文件存在。</p><p>为了演示，我将会为 Super Tux Kart 创建一个 <code>.desktop</code> 文件，这是一个我很喜欢玩的卡丁车竞赛游戏。Ubuntu 仓库中带了这个游戏，但版本一般不新。</p><p>要获得最新的版本就需要下载 tar 包，解压并执行其中的游戏启动文件。</p><p>你可以仿照这个步骤来为任何程序创建启动器。</p><p><strong>注意</strong>：下面步骤假设程序压缩包放在 “Downloads” 目录下。</p><p>1、跳转到存放压缩包的目录，右击然后选择 “Extract here”。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/11/application-launcher-5.png" alt="application-launcher-5" title="application-launcher-5"></p><p>2、解压后，进入新创建的目录然后找到可执行的文件。之后右击文件选择 “Run” 来启动程序，确定程序运行正常。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/11/application-launcher-6.png" alt="application-launcher-6" title="application-launcher-6"></p><p>3、有时候，你在右键菜单中找不到 “Run” 选项。这通常是因为这个可执行文件是一个文本文件。你可以在终端中执行它，如果你使用 GNOME 的话，可以点击上面菜单栏中的 Files 菜单，然后选择 “Preferences”。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/11/application-launcher-linux-1.png" alt="application-launcher-linux-1" title="application-launcher-linux-1"></p><p>4、选择 “Behavior” 标签页然后选择 “Executable Text Files” 下的 “Run them”。现在右击可执行文本文件后也能出现 “Run” 选项了。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/11/application-launcher-31.png" alt="application-launcher-31" title="application-launcher-31"></p><p>5、确认应用运行正常后，就可以退出它了。然后运行你的文本编辑器并将下面内容粘贴到空文本文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Desktop Entry]</span></span>
<span class="line"><span>Encoding=UTF-8</span></span>
<span class="line"><span>Version=1.0</span></span>
<span class="line"><span>Type=Application</span></span>
<span class="line"><span>Terminal=false</span></span>
<span class="line"><span>Exec=/path/to/executable</span></span>
<span class="line"><span>Name=Name of Application</span></span>
<span class="line"><span>Icon=/path/to/icon</span></span></code></pre></div><p>你需要更改 “Exec” 域的值为可执行文件的路径，并且将 “Name” 域的值改成应用的名称。大多数的程序都在压缩包中提供了一个图标，不要忘记把它也填上哦。在我们这个例子中，Super Tux Kart 的启动文件看起来是这样的：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/11/application-launcher-supertuxkart.png" alt="application-launcher-supertuxkart" title="application-launcher-supertuxkart"></p><p>6、将文件以 <code>application-name.desktop</code> 为名保存到 <code>~/.local/share/applications</code> 目录中。<code>.local</code> 目录位于你的家目录下，是一个隐藏目录，你需要启用 “Show Hidden Files” 模式才能看到它。如果你希望这个应用所有人都能访问，则在终端中运行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mv ~/.local/share/applications/&lt;application-name\`.desktop\`&gt; /usr/share/applications/</span></span></code></pre></div><p>当然，别忘了把命令中的 <code>&lt;application-name.desktop&gt;</code> 改成真实的 <code>.desktop</code> 文件名。</p><p>7、完成后，打开应用菜单，就能看到应用出现在其中，可以使用了。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/11/application-launcher-2.jpg" alt="application-launcher-2" title="application-launcher-2"></p><p>这个方法应该适用于所有主流的 Linux 操作系统。下面是另一张 Super Tux Kart 在 elementary OS 的应用启动器 (slingshot) 上的截图</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/11/application-launcher-4.jpg" alt="application-launcher-4" title="application-launcher-4"></p><p>如果你觉得本教程还有点用的话，欢迎留言。</p><hr>`,27)),i("p",null,[e[4]||(e[4]=a("via: ",-1)),p(t,{href:"https://www.maketecheasier.com/create-desktop-file-linux/"},{default:s(()=>[...e[3]||(e[3]=[a("https://www.maketecheasier.com/create-desktop-file-linux/",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=a("作者：",-1)),p(t,{href:"https://www.maketecheasier.com/author/ayoisaiah/"},{default:s(()=>[...e[5]||(e[5]=[a("Ayo Isaiah",-1)])]),_:1}),e[9]||(e[9]=a(" 译者：",-1)),p(t,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[6]||(e[6]=[a("lujun9972",-1)])]),_:1}),e[10]||(e[10]=a(" 校对：",-1)),p(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[7]||(e[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=a("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[11]||(e[11]=[a("LCTT",-1)])]),_:1}),e[14]||(e[14]=a(" 原创编译，",-1)),p(t,{href:"https://linux.cn/"},{default:s(()=>[...e[12]||(e[12]=[a("Linux中国",-1)])]),_:1}),e[15]||(e[15]=a(" 荣誉推出",-1))])])}const b=o(c,[["render",d]]);export{T as __pageData,b as default};
